solutionCode:
let packets = [
  { seq: 3, payload: "العالم البرمجي!" },
  { seq: 1, payload: "مرحباً بكم " },
  { seq: 2, payload: "في " }
];
packets.sort((a, b) => a.seq - b.seq);
let assembledMessage = packets.map(p => p.payload).join("");
console.log(assembledMessage);
